import type { TokenDictionary } from '../types.js';

/**
 * Generates the root CSS Custom Properties stylesheet.
 */
export function generateBaseCss(dict: TokenDictionary): string {
  const lines: string[] = [
    '/**',
    ' * @file Automatically generated by @pine-ui/token-compiler.',
    ' * DO NOT EDIT MANUALLY.',
    ' */',
    ':root {',
    '  /* Primitive Scales */',
  ];

  for (const token of dict.primitives.values()) {
    lines.push(`  ${token.cssVariable}: ${token.resolvedValue};`);
  }

  lines.push('', '  /* Default Semantic Tokens (Light Scheme) */');
  for (const token of dict.semantics.light.values()) {
    lines.push(`  ${token.cssVariable}: ${token.resolvedValue};`);
  }

  lines.push('}', '');

  // Accessibility: collapse motion tokens for users who prefer reduced motion.
  // Durations become near-instant and overshooting spring curves become linear,
  // so components fall back to simple opacity dissolves without code changes.
  const motionTokens = Array.from(dict.primitives.values()).filter(
    (t) => t.type === 'duration' || (t.type === 'cubicBezier' && t.path !== 'motion.easing.linear'),
  );
  if (motionTokens.length > 0) {
    lines.push('@media (prefers-reduced-motion: reduce) {', '  :root {');
    for (const token of motionTokens) {
      const value = token.type === 'duration' ? '1ms' : 'linear';
      lines.push(`    ${token.cssVariable}: ${value};`);
    }
    lines.push('  }', '}', '');
  }

  return lines.join('\n');
}

/**
 * Generates dark mode scheme overrides.
 */
export function generateDarkSchemeCss(dict: TokenDictionary): string {
  const lines: string[] = [
    '/**',
    ' * @file Automatically generated by @pine-ui/token-compiler.',
    ' * DO NOT EDIT MANUALLY.',
    ' */',
    '[data-scheme="dark"], .theme-dark {',
  ];

  for (const token of dict.semantics.dark.values()) {
    lines.push(`  ${token.cssVariable}: ${token.resolvedValue};`);
  }

  lines.push('}', '');
  return lines.join('\n');
}

