/**
 * Generates density mode CSS overrides.
 */
export function generateDensityCss(dict: TokenDictionary): string {
  const lines: string[] = [
    '/**',
    ' * @file Automatically generated by @pine-ui/token-compiler.',
    ' * DO NOT EDIT MANUALLY.',
    ' */',
  ];

  const densityModes = ['compact', 'default', 'comfortable'] as const;

  for (const mode of densityModes) {
    lines.push(`[data-density="${mode}"] {`);
    for (const token of dict.semantics.space.values()) {
      if (token.path.startsWith(`density.${mode}.`)) {
        const subPath = token.path.replace(`density.${mode}.`, '');
        lines.push(`  --pine-${subPath.replace(/\./g, '-')}: ${token.resolvedValue};`);
      }
    }
    lines.push('}', '');
  }

  return lines.join('\n');
}
